/// <summary>
/// MPJ_24248 Price data extract
/// </summary>
final class METGUPParametersFormEventHandler
{
    
}

Method.Source:
    /// <summary>
    /// Modified
    /// </summary>
    /// <param name="sender"></param>
    /// <param name="e"></param>
    [FormDataFieldEventHandler(formDataFieldStr(GUPParameters, GUPParameters, SalesOrderAttributeGroup), FormDataFieldEventType::Modified)]
    public static void SalesOrderAttributeGroup_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
    {
        FormDataSource  gupParameters_ds = sender.datasource();
        GUPParameters   gupParameters  = gupParameters_ds.cursor();

        //reset on change in value of SalesOrderAttributeGroup
        gupParameters.METSalesEventAttribute = 0;

    }

    /// <summary>
    /// Lookup
    /// </summary>
    /// <param name="sender">Form control</param>
    /// <param name="e">Event</param>
    [FormControlEventHandler(formControlStr(GUPParameters, GUPParameters_METSalesEventAttribute), FormControlEventType::Lookup)]
    public static void GUPParameters_METSalesEventAttribute_OnLookup(FormControl sender, FormControlEventArgs e)
    {
        METGUPParametersFormEventHandler::SalesEventAttributeLookup(sender);

        FormControlCancelableSuperEventArgs cancelableArgs = e as FormControlCancelableSuperEventArgs;
        cancelableArgs.CancelSuperCall();

    }

    /// <summary>
    /// Sales event attribute lookup
    /// </summary>
    /// <param name = "_ctrl">Form control</param>
    public static void SalesEventAttributeLookup(FormReferenceGroupControl _ctrl)
    {
        RefRecId    SalesOrderAttributeGroup;
        FormRun     formRun;
        FormDataSource  gupParameters_ds;
        GUPParameters   gupParameters;
        SysReferenceTableLookup sysTableLookup = SysReferenceTableLookup::newParameters(tablenum(EcoResAttribute), _ctrl);
        
        Query query = new Query(queryStr(METSalesEventAttributeLookup));

        QueryBuildDataSource qbds = query.dataSourceTable(tableNum(EcoResAttributeGroup));
        QueryBuildRange     qbr = qbds.rangeField(fieldNum(EcoResAttributeGroup, RecId));

        formRun = _ctrl.formRun() as FormRun;
        gupParameters_ds = formRun.dataSource(formDataSourceStr(GUPParameters,GUPParameters));
        gupParameters = gupParameters_ds.cursor();

        SalesOrderAttributeGroup = gupParameters.SalesOrderAttributeGroup;
        qbr.value(queryValue(SalesOrderAttributeGroup));

        sysTableLookup.addSelectionField(fieldNum(EcoResAttribute, RecId));
        sysTableLookup.addLookupfield(fieldNum(EcoResAttribute, Name));
        sysTableLookup.addLookupfield(fieldNum(EcoResAttribute, AttributeType));

        sysTableLookup.parmQuery(query);
        sysTableLookup.performFormLookup();
    }
